I(id="171d98eb-0b29-4b07-9074-359033065903",date="2015-01-28",author="WinBrun",ticker="TWX",entity="Time Warner, Inc.",group="twx",raw_short=True,direction="SOTP Long",entry="EV 약 $83bn",horizon="12~24개월",filename="analysis/ideas/2015/2015-01-28_TWX_sotp_long.md",link=None,desc=6904,cat=107,title="HBO+Turner가 EV를 덮는 residual WB SOTP Long",verdict="성공 — hidden asset·strategic scarcity 적중, HBO multiple은 공격적",score=8.0,process=8.0,
summary="raw Short지만 실제 SOTP Long이다. HBO 2015E EBITDA 최소 $2.3bn×15x=$34.5bn, Turner $4.4bn×10x=$44bn으로 합계 $78.5bn을 만들면 전체 EV 약 $83bn에서 Warner Bros.가 거의 공짜라는 residual-value 논리였다. HBO NOW와 후속 strategic buyer가 value-discovery route였다.",valuation="원문 SOTP는 HBO $34.5bn+Turner $44bn=$78.5bn에서 EV $83bn을 대부분 설명한다. 보수적으로 HBO 10~12x, Turner 8~9x로 낮추고 corporate overhead, net debt, tax leakage, shared rights를 모두 넣은 뒤 Warner Bros. implied value가 여전히 낮은지 확인해야 한다.",actual="HBO NOW는 2015년 출시됐고 2015 segment operating income은 Turner $4.087bn, HBO $1.878bn, Warner Bros. $1.416bn이었다. 2016 AT&T가 $107.50/share 거래를 발표하며 전체 IP portfolio에 control premium을 지급했다. hidden asset 논지는 맞았지만 Netflix식 comp transfer는 과감했다.",price="정확한 entry stock price와 dividend-adjusted IRR은 원 DB에 없어 null이다. AT&T strategic bid와 closing은 SOTP 방향을 검증하지만 투자자의 실제 보유수익과 동일하지 않다.",drivers="자산별 경제성을 분리하고 전체 EV에서 residual WB 가치를 역산한 것이 edge였다. HBO DTC와 strategic bid가 value discovery를 만들었고, public comp multiple이 비싸면 SOTP도 함께 부풀 수 있다는 위험은 남았다.",error="Netflix 고성장 multiple을 mature HBO에 가까이 적용하고 Turner의 cord-cutting duration을 낙관했다. corporate cost·debt·tax와 segment 간 권리관계를 더 엄격히 차감해야 했다.",first_signal="HBO NOW subscriber economics가 약하거나 Turner affiliate growth가 둔화하면 HBO 15x·Turner 10x를 동시에 낮추고 residual WB가 실제로 공짜인지 재검증해야 했다.",
metrics=[("Enterprise value","~$83bn","SOTP discount 해소","AT&T bid","성공"),("HBO","$2.3bn EBITDA×15x","$34.5bn","2015 OI $1.878bn","multiple 공격적"),("Turner","$4.4bn×10x","$44bn","2015 OI $4.087bn","대체로 성공"),("Warner Bros.","낮은 implied value","hidden value","2015 OI $1.416bn·buyer premium","성공"),("Value discovery","HBO NOW/bid","rerating","2015 launch·2016 deal","성공")],timeline=[("2014","Fox 약 $85 proposal","in-play evidence"),("2015-01-28","VIC SOTP Long","residual WB"),("2015-04","HBO NOW launch","DTC catalyst"),("2015 FY","segment actuals","SOTP 검증"),("2016-10","AT&T $107.50 agreement","strategic premium"),("2017-11","DOJ lawsuit","duration"),("2018-06","deal close","terminal")],
claimdata=[("HBO 15x","subscription·DTC quality는 high multiple을 받는다.","$2.3bn EBITDA·Netflix comp","strategic value는 컸지만 comp는 공격적이었다.","부분 성공","growth·reinvestment 차이를 조정한다."),("Turner 10x","affiliate fee와 brand가 value를 지지한다.","$4.4bn consensus EBITDA","당시 현금력은 확인됐고 장기 압력은 커졌다.","기간 성공","cash-flow duration을 explicit하게 둔다."),("WB residual value","HBO+Turner만으로 EV 대부분을 덮는다.","$78.5bn vs EV $83bn","AT&T가 전체 portfolio에 premium을 지급했다.","성공","SOTP는 residual implied value가 핵심이다."),("HBO NOW catalyst","standalone product가 hidden value를 드러낸다.","2015 launch 예정","월 $14.99 서비스가 출시됐다.","성공","product event와 earnings contribution을 나눈다."),("strategic optionality","Fox 철회 뒤에도 다른 buyer가 올 수 있다.","prior $85 proposal","AT&T가 $107.50 agreement를 맺었다.","강한 성공","control premium을 확률가중한다."),("SOTP convergence","시장가가 parts에 접근한다.","WB가 거의 공짜인 역산","strategic deal로 방향이 실현됐다.","성공","value-discovery route 없는 SOTP를 경계한다.")]),

