def main():
    assert len(IDEAS) == 10 and len({i["id"] for i in IDEAS}) == 10
    for idea in IDEAS:
        assert len(idea["claims"]) == 6 and len(idea["metrics"]) == 5 and len(idea["timeline"]) >= 6
        text = m.report(idea)
        generic_performance = "이번 10건은 첨부 SQL에 performance row가 없으므로 1개월~5년 수익률을 만들지 않는다. 사건 성공, 기업 생존, target 도달과 투자 total return을 각각 별도 필드로 둔다. corporate action이 있으면 successor security까지 연결돼야 정확한 IRR을 계산할 수 있다."
        if idea["id"] in PERF:
            text = text.replace(generic_performance, "이 아이디어는 repository에 보존된 price multiplier를 실제 Long 방향으로 교정했다. `multiplier-1`은 price-only 수익이며 배당·preferred dilution·거래비용을 포함하지 않는다. 누락 horizon은 null이다.")
        else:
            text = text.replace(generic_performance, "이 아이디어는 첨부 SQL과 repository source layer에 검증된 performance row가 없어 1개월~5년 수익률을 만들지 않는다. 사건 성공, target 달성과 투자 total return을 각각 별도 필드로 두며 누락값은 null이다.")
        text = text.replace(f"1. **Entity audit:** `ATH`를 회사로 보지 말고 {idea['entity']} 법인·exchange·날짜로 고정한다.", f"1. **Entity audit:** ticker `{idea['ticker']}`만 보지 말고 {idea['entity']}의 법인·증권·날짜로 고정한다.")
        path = ROOT / idea["filename"]
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text, encoding="utf-8")
    parts = [Path(i["filename"]).relative_to("analysis").as_posix() for i in IDEAS]
    wrapper = "# Batch 048 — KAR / Time Warner / Metals USA V9\n\n" + f"<!-- batch_parts: {'|'.join(parts)} -->\n\n" + "> Streamlit 호환 wrapper다. canonical index: [Batch 048 V9 Index](batch_048_v9_index.md).\n"
    (ROOT / "analysis/batch_048_kar_timewarner_metalsusa_10.md").write_text(wrapper, encoding="utf-8")
    (ROOT / "analysis/batch_048_v9_index.md").write_text(make_index(IDEAS), encoding="utf-8")
    payload = patch_performance(m.make_payload(IDEAS))
    payload["batch"] = 48
    payload["title"] = "KAR / Time Warner / Metals USA — Direction, Security, Duration and Event Path V9"
    payload["research_asof"] = ASOF
    (ROOT / "data/curated/batch_048_kar_timewarner_metalsusa_deep_v7.json").write_text(json.dumps(payload, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    packet = {"batch": "048", "format": "V9-per-idea", "source": "VIC_IDEAS(4).sql + repository source metadata", "record_count": 10, "direction_audit": "complete", "direction_corrections": 8, "performance_rows_preserved": 2, "performance_rule": "KAR 2건만 보존 multiplier를 실제 Long 방향으로 교정; 나머지는 null", "candidates": [{"idea_id": i["id"], "date": i["date"], "ticker": i["ticker"], "company_name": i["entity"], "author": i["author"], "raw_direction": "Short" if i["raw_short"] else "Long", "research_direction": i["direction"], "description_chars": i["desc"], "catalyst_chars": i["cat"], "performance_available": i["id"] in PERF, "canonical_report": i["filename"]} for i in IDEAS]}
    (ROOT / "data/curated/batch_048_source_packet.json").write_text(json.dumps(packet, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    inventory = {"source_filename": "VIC_IDEAS(4).sql", "attachment_bytes_checked": 122499072, "records_selected": 10, "raw_descriptions_present_in_attachment": 5, "raw_catalysts_verified": 10, "repository_performance_rows_preserved": 2, "direction_corrections": 8, "entity_corrections": 1, "note": "첨부 SQL은 10건 catalyst와 5건 description을 포함했다. 누락 description은 길이를 0으로 유지했다. KAR 2건의 repository multiplier 외 성과는 만들지 않았다."}
    (ROOT / "data/curated/batch_048_sql_inventory.json").write_text(json.dumps(inventory, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print({k: len(payload[k]) for k in ("ideas_master", "postmortems", "sections", "claims", "metrics", "timeline", "sources")})

if __name__ == "__main__":
    main()
